from pathlib import Path
from collections import defaultdict,Counter
import cv2,numpy as np
ROOT=Path(__file__).resolve().parent;BASE=ROOT.parent/'ball_quality_20261110';FOLLOW=BASE/'automatic_reacquisition_followup';CASE=BASE/'cohort_tracking/case_011';OUT=FOLLOW/'case_011/four_player_experiment'
