    farther=read(far.OUT/'players_011_global/far_pair_path.csv');slots=['near_front','near_rear','far_rear','far_front'];combined=sorted(near+farther,key=lambda r:(int(r['source_frame']),slots.index(r['player_slot'])));write(OUT/'four_player_path.csv',combined)
