    for r in combined:
        f=int(r['source_frame']);assert r['player_slot'] not in people[f];people[f][r['player_slot']]=r
        assert any(all(r[k]==x[k] for k in ['x1','y1','x2','y2','bottom_center_x','bottom_center_y','confidence']) for x in native[f,r['track_id']])
    for ps in people.values():assert len({r['track_id'] for r in ps.values()})==len(ps)
    times=p['requested_input_frames'];cid=p['candidate_id'];features=[dict(rally_candidate_id=cid,relative_source_frame=f-times[0],**pair_features(people[f])) for f in times];snap,summ,_=summarize_prefix('011',[dict(r,ball_observation_present=0,ball_x_norm='',ball_y_norm='') for r in features])
    for name,rows in [('prefix_frame_features.csv',features),('snapshot_player_features.csv',[snap]),('prefix_player_summary_features.csv',[summ])]:write(OUT/name,rows)
    expected=[calculate_frame(cid,people,f,f-times[0]) for f in times];checked=0
    for a,b in zip(features,expected):
        for k,v in b.items():
            if k!='rally_candidate_id':close(a[k],v);checked+=1
    es,em=calculate_summary(expected)
    for a,b in [(snap,es),(summ,em)]:
        for k,v in b.items():close(a[k],v);checked+=1
    views=[27222,27223,27237,27385,27514,27854,28140,28286,28881];cells=[];cap=cv2.VideoCapture(p['source_video']);colors=[(80,255,80),(255,190,40),(255,80,240),(0,230,255)]
    for f in views:
        cap.set(1,f);ok,im=cap.read();assert ok and round(cap.get(1))==f+1
        for i,s in enumerate(slots):
            r=people[f].get(s)
            if not r:continue
            b=[round(float(r[k])) for k in ['x1','y1','x2','y2']];cv2.rectangle(im,tuple(b[:2]),tuple(b[2:]),colors[i],5);cv2.putText(im,['N1','N2','F1','F2'][i]+' raw'+r['track_id'],(b[0],max(35,b[1]-12)),0,1.2,colors[i],3)
        thumb=cv2.resize(im,(960,540),interpolation=cv2.INTER_AREA);head=np.zeros((34,960,3),np.uint8);cv2.putText(head,f'Automatic guard F{f} {len(people[f])}/4 observed',(10,25),0,.8,(255,255,255),1);cells.append(np.vstack([head,thumb]))
    cap.release();cv2.imwrite(str(OUT/'candidate_sequence_grid.jpg'),np.vstack([np.hstack(cells[i:i+3]) for i in range(0,len(cells),3)]))
    video=far.OUT/'players_011_global/global_review_h264.mp4';cap=cv2.VideoCapture(str(video));count=0
    while True:
        ok,im=cap.read()
        if not ok:break
        assert im.shape[:2]==(1080,1920);count+=1
    cap.release();assert count==p['context_last_source_frame']-p['context_first_source_frame']+1
    assert all(sha(Path(n))==h for n,h in protected.items())
    report=dict(status='passed',matched_native_boxes=len(combined),recalculated_feature_values=checked,manual_ID_binding=False,canonical_pipeline_changed=False,interpolation=False,duplicate_slot_or_raw_ID_assignments=False,video_frames_decoded=count,four_observation_requested_times=sum(len(people[f])==4 for f in times),requested_times=31,selected_slot_counts=dict(Counter(r['player_slot'] for r in combined)),prefix_features_equal_baseline=all(read(OUT/n)==read(CASE/n) for n in ['prefix_frame_features.csv','snapshot_player_features.csv','prefix_player_summary_features.csv']),QA_source_frames=views,far_search_uses_future_context=True,independent_identity_or_position_accuracy_established=False,protected_sources_unchanged=True)
    dump(OUT/'verification.json',report);print(json.dumps(report),flush=True)
